/* Insurance expiry alerts on the notifications bell. */
(function(){
 const daysToExpiry=r=>{if(!r?.expiry)return null;let d=new Date(r.expiry+'T00:00:00'),t=new Date(today()+'T00:00:00');if(Number.isNaN(d.getTime()))return null;return Math.ceil((d-t)/86400000)};
 const duePolicies=()=>db.insurance.map(r=>({r,days:daysToExpiry(r)})).filter(x=>x.days!==null&&x.days<=30).sort((a,b)=>a.days-b.days);
 const pendingJobs=()=>db.jobs.filter(r=>r.status==='Pending');
 function refreshAlertBell(){let button=$('#notifications');if(!button)return;let count=duePolicies().length+pendingJobs().length;button.setAttribute('aria-label',count?`${count} alerts, including insurance due and pending jobs`:'No current alerts');button.title=count?`${count} current alerts`:'No current alerts';let badge=button.querySelector('.alertCount');if(count){if(!badge){badge=document.createElement('span');badge.className='alertCount';button.append(badge)}badge.textContent=count>99?'99+':String(count)}else badge?.remove()}
 function openAlerts(){let insurance=duePolicies(),jobs=pendingJobs();let body=insurance.length?`<h3>Insurance due or expired</h3><div class="tablewrap"><table><thead><tr><th>Vehicle</th><th>Customer</th><th>Insurance Company / Policy</th><th>Expiry</th><th>Status</th><th>Action</th></tr></thead><tbody>${insurance.map(({r,days})=>{let c=policyContact(r);return `<tr><td>${esc(c.vehicle||'—')}</td><td>${esc(c.name||'—')}</td><td>${esc(r.policy||'—')}<br>${esc(r.provider||'—')}</td><td>${esc(typeof displayDate==='function'?displayDate(r.expiry):r.expiry)}</td><td><strong style="color:${days<0?'#b42318':days===0?'#b54708':'#b54708'}">${days<0?`Expired ${Math.abs(days)} day(s) ago`:days===0?'Due today':`Due in ${days} day(s)`}</strong></td><td>${extraButton('whatsapp','insurance',r.id,'Send policy details and documents by WhatsApp','green','WhatsApp')}</td></tr>`}).join('')}</tbody></table></div>`:'<p>No insurance policies are due within the next 30 days.</p>';let jobSection=`<div class="notice" style="margin-top:14px">Pending job cards: <strong>${jobs.length}</strong> ${jobs.length?'<button type="button" class="btn small" id="pendingJobsView">View jobs</button>':''}</div>`;openModal('Alerts & Reminders',`<div class="formbody">${insurance}${jobSection}<p style="color:#64748b">Insurance alerts include policies due within 30 days and all expired policies.</p></div><div class="formactions"><button type="button" class="btn secondary" data-action="cancel">Close</button>${insurance.length?'<button type="button" class="btn" id="insuranceAlertsView">Open Insurance</button>':''}</div>`);$('#insuranceAlertsView')?.addEventListener('click',()=>{closeModal();go('insurance')});$('#pendingJobsView')?.addEventListener('click',()=>{closeModal();go('jobs');filter='Pending';render()})}
 let originalRender=render;render=function(){originalRender();refreshAlertBell()};
 $('#notifications').onclick=openAlerts;
 const style=document.createElement('style');style.textContent='#notifications{position:relative}.alertCount{position:absolute;right:-2px;top:-3px;min-width:17px;height:17px;padding:0 4px;border-radius:10px;background:#dc2626;color:#fff;font-size:10px;font-weight:800;line-height:17px;text-align:center;box-shadow:0 0 0 2px white}';document.head.append(style);
 refreshAlertBell();
})();
